/**
 * The Vineyard
 * ------------
 * Noah plants a vineyard, drinks the wine, and is uncovered in his tent; Ham sees, Shem and Japheth cover him. Stage: a vineyard in the afternoon, a man resting in a tent, a son coming in with a garment, the father's shame and blessing; the first vineyard, the first family, the first sorrow.
 *
 * Palette 0x1a0e08 → 0x0c0604 · light: ember · hero: tent
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./noah-kit.js.
 */

import { THREE, createScene, tent, firepit, vineyard, person } from './noah-kit.js';

const BG = 0x1a0e08;
const GROUND = 0x040202;

export function build(group) {
    const W = createScene(group, { seed: 2883901275, bg: BG, fogNear: 45, fogFar: 180 });

    /* light — ember */
    W.lights({ sky: 0x3a2418, gnd: 0x1a0e08, hemi: 0.4, sun: 0xff7a30, sunI: 0.7, sunPos: [20, 26, 30] });

    W.stars(90, 150, [0xf0e0c8, 0xd8c0a0], 0.7);
    W.disc([0, 34, -150], 14, 0xff8a30, 0.12);

    /* ground */
    W.ground(260, 260, 0, 0, 0x040202, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* camp: a circle of tents, smoke rising */
    tent(W, group, -12.7, 0, -0.9, 1.11, 0xa8704a, W.r() * 6);
    tent(W, group, -2.1, 0, -9.7, 1.21, 0xc8b088, W.r() * 6);
    tent(W, group, -6.5, 0, -10.9, 1.19, 0xd8c8a0, W.r() * 6);
    tent(W, group, -23.4, 0, -11.2, 1.34, 0xd8c8a0, W.r() * 6);
    tent(W, group, -5.0, 0, -11.2, 1.37, 0xd8c8a0, W.r() * 6);
    firepit(W, group, 7.6, 0, -1.0, 1.0);

    /* vineyard: posts, canopies, hanging fruit */
    vineyard(W, group, 0, 30, 40, 80, { leaf: 0x4f8a2e, berry: 0x120a06 });

    /* hero: the tent */
    tent(W, group, 0, 0, 0, 1.4, 0x0c0604, 0.2);
    W.disc([0, 5, -10], 5, 0x22120a, 0.3);

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0x1a0e08, ry: -0.45, s: 1.17 });

    return W.finish();
}

export default { build };
